<template>
  <div class="page"><div class="page-heading"><div><h1>供应商管理</h1><p>维护供应商资料、信用等级和合作状态。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">新增供应商</el-button></div><el-card class="panel-card filter-card"><el-input v-model="keyword" clearable placeholder="搜索供应商名称、联系人或电话" :prefix-icon="Search" /></el-card><el-card class="panel-card"><el-table v-loading="loading" :data="displayRows" stripe><el-table-column prop="name" label="供应商名称" min-width="220" /><el-table-column prop="contact" label="联系人" width="120" /><el-table-column prop="phone" label="联系电话" width="155" /><el-table-column prop="address" label="地址" min-width="190" /><el-table-column prop="creditLevel" label="信用等级" width="110"><template #default="{ row }"><el-tag :type="row.creditLevel === 'A' ? 'success' : 'warning'">{{ row.creditLevel }}级</el-tag></template></el-table-column><el-table-column prop="status" label="状态" width="100"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column><template #empty><el-empty description="暂无供应商" /></template></el-table></el-card></div>
  <el-dialog v-model="dialogVisible" :title="editing ? '编辑供应商' : '新增供应商'" width="520px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="供应商名称" prop="name"><el-input v-model="form.name" /></el-form-item><el-form-item label="联系人" prop="contact"><el-input v-model="form.contact" /></el-form-item><el-form-item label="联系电话" prop="phone"><el-input v-model="form.phone" /></el-form-item><el-form-item label="地址"><el-input v-model="form.address" /></el-form-item><el-form-item label="信用等级"><el-select v-model="form.creditLevel"><el-option label="A级" value="A" /><el-option label="B级" value="B" /><el-option label="C级" value="C" /></el-select></el-form-item></el-form><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { api } from '../api'; import StatusTag from '../components/StatusTag.vue'; import { Plus, Search } from '@element-plus/icons-vue'
const loading = ref(false); const saving = ref(false); const rows = ref([]); const keyword = ref(''); const dialogVisible = ref(false); const editing = ref(false); const formRef = ref(); const form = reactive({ id: null, name: '', contact: '', phone: '', address: '', creditLevel: 'A' }); const rules = { name: [{ required: true, message: '请输入供应商名称', trigger: 'blur' }], contact: [{ required: true, message: '请输入联系人', trigger: 'blur' }], phone: [{ required: true, message: '请输入联系电话', trigger: 'blur' }] }; const displayRows = computed(() => { const text = keyword.value.toLowerCase(); return rows.value.filter((x) => !text || (x.name + x.contact + x.phone).toLowerCase().includes(text)) })
async function load() { loading.value = true; try { const data = await api.suppliers(); rows.value = data?.records || data?.data?.records || data || [] } finally { loading.value = false } } function openCreate() { editing.value = false; Object.assign(form, { id: null, name: '', contact: '', phone: '', address: '', creditLevel: 'A' }); dialogVisible.value = true } function openEdit(row) { editing.value = true; Object.assign(form, row); dialogVisible.value = true } async function save() { const valid = await formRef.value.validate().catch(() => false); if (!valid) return; saving.value = true; try { if (editing.value) await api.updateSupplier(form.id, form); else await api.createSupplier(form); ElMessage.success('供应商已保存'); dialogVisible.value = false; load() } finally { saving.value = false } } async function remove(row) { const confirmed = await ElMessageBox.confirm('确认删除供应商“' + row.name + '”？', '删除确认', { type: 'warning' }).then(() => true).catch(() => false); if (!confirmed) return; await api.deleteSupplier(row.id); ElMessage.success('已删除'); load() } onMounted(load)
</script>
